import { z } from 'zod';

/*
 * Canonical source of the v2 segment families added by the first-release
 * catalog (GAP-FIX-R1 learning, B.7 / Appendix P Part 8, B.8, B.9, B.11,
 * B.18). Core's contract (v2LessonDocument.ts) composes these schemas; the
 * browser copy (frontend/src/rebuild/learning/v2SegmentFamilies.generated.ts)
 * is generated byte-for-byte by agent/tools/sync-v2-segment-families.mjs and
 * `npm run spec:check` fails on drift, the same posture as the scorer.
 *
 * Every payload here is answerless: which card must be flipped, which region
 * or bin an item belongs to, which message is a scam, the path through a
 * flowchart, the amount to make and the acceptable story choice all live in
 * Core's private rubric (`V2_FAMILY_RUBRICS`), never in the document.
 *
 * This module must stay self-contained (zod only): it is copied verbatim.
 */

export const V2_ID_PATTERN = /^[a-z0-9][a-z0-9._:-]{2,100}$/;
const id = z.string().regex(V2_ID_PATTERN);
const positive = z.number().int().positive().safe();
const label = (max: number) => z.string().trim().min(1).max(max);
const option = z.object({ id, label: label(80) }).strict();

/**
 * Optional fields every v2 segment may carry (all three copies):
 * - `help`: up to two ladder steps shown on request, one speech-plate turn
 *   each (Bible 08 §11, Appendix A Part 2 "help available on request").
 * - `item_role`: practice or transfer (Appendix C 1.1 transfer success).
 * - `knowledge_component_id`: the KC this item evidences; it must be one of
 *   the document's `knowledge_component_ids`.
 */
export const v2SegmentExtras = {
  help: z.array(label(160)).min(1).max(2).optional(),
  item_role: z.enum(['practice', 'transfer']).optional(),
  knowledge_component_id: id.optional(),
  // Appendix P Part 8 (GAP-FIX-R2): L12/$11 items before and after the lesson (d-prime pre/post),
  // and the representation variant an A/B comparison groups transfer success by.
  item_phase: z.enum(['pre', 'post']).optional(),
  variant: id.optional(),
};

function uniqueIds(values: ReadonlyArray<{ id: string }>): boolean {
  return new Set(values.map((value) => value.id)).size === values.length;
}

/* ── Logic (Appendix P Part 8: L1, L5, L6, L10, L12) ─────────────────────── */

/**
 * L1 (GAP-FIX-R3, Appendix P L1 and Part 4.5): each card's logical role
 * against the rule "if P then Q", kept in the PRIVATE rubric only. The
 * roles let the scorer store a selection-task diagnostic ({P, Q} is
 * confirmation bias) instead of a generic miss.
 */
export const RULE_CARD_ROLES = ['p', 'not_p', 'q', 'not_q'] as const;
export type RuleCardRole = (typeof RULE_CARD_ROLES)[number];

/**
 * L1: a conditional rule and the cards that could break it; the learner flips
 * the ones that must be checked. `rule_kind` (GAP-FIX-R4, Appendix P L1 ages
 * column): 6-12 use permission rules only; abstract and causal rules open at
 * 13 (v2PayloadScopeProblem). Absent: a permission rule.
 */
export const RULE_KINDS = ['permission', 'abstract', 'causal'] as const;
export const ruleCheckerPayload = z.object({
  rule: label(160),
  rule_kind: z.enum(RULE_KINDS).optional(),
  cards: z.array(z.object({ id, face: label(24) }).strict()).min(3).max(6),
}).strict().refine((value) => uniqueIds(value.cards), 'Invalid rule cards');

/**
 * L5: two sets drawn as an Euler diagram; items are placed in regions.
 * GAP-FIX-R4 (Appendix P L5 "Place items; pick the diagram that matches a
 * sentence"; graded on "item->region map; region occupancy flags; chosen
 * conclusion"; syllogisms for 13-17):
 * - either the payload declares the `relation`, or `choose_relation` asks the
 *   learner to pick which of the three diagrams matches the `sentence` (the
 *   right one is in the private rubric);
 * - `mark_occupancy` asks the learner to mark which regions hold something
 *   (the rubric's `occupied`);
 * - `conclusion` (13-17 and adults) asks whether its statement follows
 *   necessarily, possibly or never (the rubric's `conclusion`).
 */
export const EULER_REGIONS = ['first', 'second', 'both', 'neither'] as const;
export const EULER_RELATIONS = ['overlap', 'subset', 'disjoint'] as const;
export const EULER_CONCLUSIONS = ['necessarily', 'possibly', 'never'] as const;
export const eulerPayload = z.object({
  relation: z.enum(EULER_RELATIONS).optional(),
  choose_relation: z.literal(true).optional(),
  sentence: label(200).optional(),
  sets: z.tuple([option, option]),
  items: z.array(option).min(2).max(6),
  mark_occupancy: z.literal(true).optional(),
  conclusion: z.object({ statement: label(200) }).strict().optional(),
}).strict().refine((value) => uniqueIds([...value.sets, ...value.items])
  && (value.relation === undefined) === (value.choose_relation === true)
  && (value.choose_relation !== true || value.sentence !== undefined), 'Invalid Euler items');

/** The regions a relation can hold: nothing is only-in-A when A sits inside B; nothing is in both when they never meet. */
export function eulerRegions(relation: (typeof EULER_RELATIONS)[number]): Array<(typeof EULER_REGIONS)[number]> {
  return relation === 'subset' ? ['second', 'both', 'neither'] : relation === 'disjoint' ? ['first', 'second', 'neither'] : ['first', 'second', 'both', 'neither'];
}

/** L6 / $9: a steppable flowchart or decision tree walked once per scenario. */
const flowNode = z.object({
  id, kind: z.enum(['question', 'outcome']), label: label(80), yes: id.optional(), no: id.optional(),
}).strict();
export const flowchartPayload = z.object({
  start: id,
  nodes: z.array(flowNode).min(3).max(12),
  scenarios: z.array(option).min(1).max(3),
}).strict().refine((value) => validFlowchart(value), 'Invalid flowchart');

export type FlowchartPayload = z.infer<typeof flowchartPayload>;

function validFlowchart(value: { start: string; nodes: Array<{ id: string; kind: string; yes?: string; no?: string }>; scenarios: Array<{ id: string }> }): boolean {
  if (!uniqueIds(value.nodes) || !uniqueIds(value.scenarios)) return false;
  const byId = new Map(value.nodes.map((node) => [node.id, node]));
  const start = byId.get(value.start);
  if (!start || start.kind !== 'question') return false;
  for (const node of value.nodes) {
    if (node.kind === 'question' && (!node.yes || !node.no || !byId.has(node.yes) || !byId.has(node.no) || node.yes === node.no)) return false;
    if (node.kind === 'outcome' && (node.yes !== undefined || node.no !== undefined)) return false;
  }
  // Acyclic and every node reachable from the start: a walk always ends.
  const state = new Map<string, 'open' | 'done'>();
  const visit = (nodeId: string): boolean => {
    const mark = state.get(nodeId);
    if (mark === 'open') return false;
    if (mark === 'done') return true;
    state.set(nodeId, 'open');
    const node = byId.get(nodeId)!;
    const ok = node.kind === 'outcome' || (visit(node.yes!) && visit(node.no!));
    state.set(nodeId, 'done');
    return ok;
  };
  return visit(value.start) && state.size === value.nodes.length;
}

/**
 * L10 / $10: sort items into bins by a rule and say why; one bin may be "it
 * depends". GAP-FIX-R4 (Appendix P L10 "6-9 single rule; 10-12 rule switch
 * and 'it depends'"; "the rule changes mid-task"): `depends_bin_id` is
 * optional (a 6-9 single-rule sort has none), and `switch_after` with
 * `second_bins` (and the new rule's `second_rule` text) changes the rule
 * after that many items: the items from that index on go into the second bin
 * set. The rubric names each item's accepted (bin, reason) pairs from its own
 * phase; Core grades each phase.
 */
export const sortBinsPayload = z.object({
  rule: label(160).optional(),
  bins: z.array(option).min(2).max(4),
  depends_bin_id: id.optional(),
  items: z.array(option).min(2).max(8),
  reasons: z.array(option).min(2).max(5),
  switch_after: z.number().int().min(1).max(7).optional(),
  second_rule: label(160).optional(),
  second_bins: z.array(option).min(2).max(4).optional(),
}).strict().refine((value) => uniqueIds([...value.bins, ...(value.second_bins ?? []), ...value.items, ...value.reasons])
  && (value.depends_bin_id === undefined || value.bins.some((bin) => bin.id === value.depends_bin_id))
  && (value.switch_after === undefined) === (value.second_bins === undefined)
  && (value.switch_after === undefined) === (value.second_rule === undefined)
  && (value.switch_after === undefined || value.switch_after < value.items.length), 'Invalid sort bins');

/** The bins an item may go into: its phase's set (GAP-FIX-R4 rule switch). */
export function sortPhaseBins<T extends { id: string }>(payload: { bins: T[]; second_bins?: T[]; switch_after?: number; items: Array<{ id: string }> }, itemId: string): T[] {
  const index = payload.items.findIndex((item) => item.id === itemId);
  return payload.switch_after !== undefined && payload.second_bins && index >= payload.switch_after ? payload.second_bins : payload.bins;
}

/** L12 / $11: messages to classify; genuine messages are always in the set (enforced by the rubric). */
export const messageListPayload = z.object({
  messages: z.array(z.object({ id, sender: label(40), text: label(200) }).strict()).min(3).max(8),
  // L12 (GAP-FIX-R2): the public cue list the learner ticks per message ("tick which cues fired").
  cues: z.array(option).min(2).max(6).optional(),
}).strict().refine((value) => uniqueIds([...value.messages, ...(value.cues ?? [])]), 'Invalid messages');

/* ── Money ($1, $2) ───────────────────────────────────────────────────────── */

const denomination = z.object({ value_minor: positive.max(100_000), kind: z.enum(['coin', 'bill']), available: positive.max(20) }).strict();
const denominations = z.array(denomination).min(2).max(8)
  .refine((values) => values.every((value, index) => index === 0 || value.value_minor < values[index - 1]!.value_minor), 'Denominations must be strictly descending');

/** $1: build an amount from a tray of coins and bills (integer minor units). */
export const coinTrayPayload = z.object({ currency: z.enum(['coins', 'local']), denominations }).strict();

/** $2: make change; price and payment are public, the change owed is private. */
export const makingChangePayload = z.object({
  currency: z.enum(['coins', 'local']), denominations,
  price_minor: positive.max(1_000_000), paid_minor: positive.max(1_000_000),
}).strict().refine((value) => value.paid_minor > value.price_minor, 'Payment must exceed the price');

/* ── Story and Mentor voice (B.8, B.9, B.11, B.18) ────────────────────────── */

export const storyBranchPayload = z.object({ scene: label(300), options: z.array(option).min(2).max(3) }).strict()
  .refine((value) => uniqueIds(value.options), 'Invalid story options');
export const dialogueChoicePayload = z.object({ speaker: label(40), line: label(200), replies: z.array(option).min(2).max(3) }).strict()
  .refine((value) => uniqueIds(value.replies), 'Invalid dialogue replies');
export const wouldYouRatherPayload = z.object({ options: z.tuple([option, option]) }).strict()
  .refine((value) => value.options[0].id !== value.options[1].id, 'Invalid would-you-rather options');

/**
 * B.18: the narration channel. `text_only` voices nothing; `differentiated`
 * carries a script that says more than the on-screen line, so Forge gate 11
 * can prove the plate is a caption and not a transcript.
 */
export const narrationChannel = z.object({
  mode: z.enum(['text_only', 'differentiated']),
  script: label(400).optional(),
  audio_ref: id.optional(),
}).strict().refine((value) => value.mode === 'text_only' ? value.script === undefined && value.audio_ref === undefined : value.script !== undefined,
  'Invalid narration channel');

/** B.8: the learner's Mentor introduces, bridges or wraps a lesson in one speech-plate turn. The character is always the learner's own (OD-19). */
export const mentorTurnPayload = z.object({
  role: z.enum(['intro', 'transition', 'wrap']),
  line: label(160),
  narration: narrationChannel.optional(),
}).strict();

/** B.11: a flawed, human decision voiced by the Mentor, then its recovery. Character-agnostic lines. */
export const mentorEpisodePayload = z.object({
  setup: label(160), misjudgment: label(160), recovery: label(160),
  narration: narrationChannel.optional(),
}).strict();

/* ── $6 unit-price comparator (GAP-FIX-R2) ─────────────────────────────────── */

/**
 * Appendix P $6 (built on M14): two or three offers, each a quantity and a
 * price; the learner finds the unit price of each ("Always show the unit")
 * and picks the better choice. The exact rational unit prices and the better
 * offer are private; unit prices must all differ so the better choice is
 * unique.
 */
export const unitPricePayload = z.object({
  currency: z.enum(['coins', 'local']),
  unitLabel: label(24),
  offers: z.array(z.object({ id, label: label(40), quantity: positive.max(1_000), price_minor: positive.max(1_000_000) }).strict()).min(2).max(3),
}).strict().refine((value) => uniqueIds(value.offers) && value.offers.every((a, i) => value.offers.every((b, j) => i === j
  || a.price_minor * b.quantity !== b.price_minor * a.quantity)), 'Invalid unit-price offers');

/* ── L2 IF-THEN-ELSE rule builder, and L6/$9 built flowcharts (GAP-FIX-R2) ── */

/**
 * Appendix P L2: condition and action tiles build IF <expression> THEN
 * <action> ELSE <action>; ages 8-9 use a single IF, 10-12 add AND/OR, 13-17
 * and adults nest and negate (`level`). The public practice cards let the
 * learner run the rule; Core grades it by behaviour on a fixed hidden set of
 * 5-10 scenarios in the private rubric, never by tile layout (Part 4.6).
 */
export const RULE_LEVELS = ['single', 'connective', 'nested'] as const;
const facts = z.record(id, z.boolean());
export const ruleBuilderPayload = z.object({
  level: z.enum(RULE_LEVELS),
  conditions: z.array(option).min(1).max(4),
  actions: z.array(option).min(2).max(3),
  practice: z.array(z.object({ id, label: label(80), facts }).strict()).min(1).max(4),
}).strict().refine((value) => uniqueIds([...value.conditions, ...value.actions, ...value.practice])
  && value.practice.every((card) => sameKeys(card.facts, value.conditions.map((condition) => condition.id)))
  && (value.level !== 'single' || value.conditions.length >= 1) && (value.level === 'single' || value.conditions.length >= 2), 'Invalid rule builder');

function sameKeys(record: Record<string, unknown>, keys: readonly string[]): boolean {
  return Object.keys(record).length === keys.length && keys.every((key) => Object.hasOwn(record, key));
}

/**
 * L6 "13-17 build their own" / $9 "built by older learners and tested on
 * scenarios": the learner places question and outcome nodes; Core evaluates
 * the tree on the hidden cases of the rubric. Public practice cases carry
 * their answers so the learner can test the tree before checking.
 */
export const flowchartBuildPayload = z.object({
  mode: z.literal('build'),
  questions: z.array(option).min(1).max(3),
  outcomes: z.array(option).min(2).max(3),
  practice: z.array(z.object({ id, label: label(80), answers: facts }).strict()).min(1).max(4),
}).strict().refine((value) => uniqueIds([...value.questions, ...value.outcomes, ...value.practice])
  && value.practice.every((card) => sameKeys(card.answers, value.questions.map((question) => question.id))), 'Invalid flowchart build');

/* ── Segments ─────────────────────────────────────────────────────────────── */

const base = { id, prompt: z.string().trim().min(1).max(500), ...v2SegmentExtras };
const server = z.literal('server');
const visual = <T extends string>(type: T) => z.object({ type: z.literal(type) }).strict();

export const v2FamilySegments = [
  z.object({ ...base, type: z.literal('logic.rule-checker.v2'), grading: server, visual: visual('rule-cards'), payload: ruleCheckerPayload }).strict(),
  z.object({ ...base, type: z.literal('logic.euler.v2'), grading: server, visual: visual('euler'), payload: eulerPayload }).strict(),
  z.object({ ...base, type: z.literal('logic.flowchart.v2'), grading: server, visual: visual('flowchart'), payload: z.union([flowchartPayload, flowchartBuildPayload]) }).strict(),
  z.object({ ...base, type: z.literal('money.spend-decision.v2'), grading: server, visual: visual('decision-tree'), payload: z.union([flowchartPayload, flowchartBuildPayload]) }).strict(),
  z.object({ ...base, type: z.literal('logic.sort-by-rule.v2'), grading: server, visual: visual('sort-bins'), payload: sortBinsPayload }).strict(),
  z.object({ ...base, type: z.literal('money.needs-wants.v2'), grading: server, visual: visual('sort-bins'), payload: sortBinsPayload }).strict(),
  z.object({ ...base, type: z.literal('logic.scam-spotter.v2'), grading: server, visual: visual('message-list'), payload: messageListPayload }).strict(),
  z.object({ ...base, type: z.literal('money.scam-check.v2'), grading: server, visual: visual('message-list'), payload: messageListPayload }).strict(),
  z.object({ ...base, type: z.literal('money.coin-tray.v2'), grading: server, visual: visual('coin-tray'), payload: coinTrayPayload }).strict(),
  z.object({ ...base, type: z.literal('money.making-change.v2'), grading: server, visual: visual('coin-tray'), payload: makingChangePayload }).strict(),
  z.object({ ...base, type: z.literal('story.branch.v2'), grading: server, visual: visual('story-scene'), payload: storyBranchPayload }).strict(),
  z.object({ ...base, type: z.literal('story.dialogue-choice.v2'), grading: server, visual: visual('dialogue'), payload: dialogueChoicePayload }).strict(),
  z.object({ ...base, type: z.literal('story.would-you-rather.v2'), grading: server, visual: visual('would-you-rather'), payload: wouldYouRatherPayload }).strict(),
  // GAP-FIX-R2: $6 unit-price comparator and the L2 rule builder.
  z.object({ ...base, type: z.literal('money.unit-price.v2'), grading: server, visual: visual('ratio-table'), payload: unitPricePayload }).strict(),
  z.object({ ...base, type: z.literal('logic.rule-builder.v2'), grading: server, visual: visual('rule-builder'), payload: ruleBuilderPayload }).strict(),
  z.object({ ...base, type: z.literal('voice.mentor-turn.v2'), grading: z.literal('none'), visual: visual('speech-plate'), payload: mentorTurnPayload }).strict(),
  z.object({ ...base, type: z.literal('voice.mentor-episode.v2'), grading: z.literal('none'), visual: visual('speech-plate'), payload: mentorEpisodePayload }).strict(),
] as const;

export type V2FamilySegment = z.infer<(typeof v2FamilySegments)[number]>;
export type V2FamilyType = V2FamilySegment['type'];

/** The segment kinds whose choice is a story decision for the B.9 journal. */
export const V2_STORY_TYPES = ['story.branch.v2', 'story.dialogue-choice.v2', 'story.would-you-rather.v2'] as const;

/* ── Private rubrics (Core only; the browser never receives them) ─────────── */

const ids = (min: number, max: number) => z.array(id).min(min).max(max);
/** L2 rule expression: a condition, NOT, or a binary AND/OR (the level caps which shapes a rule may take). */
export type RuleExpr = { c: string } | { not: RuleExpr } | { and: [RuleExpr, RuleExpr] } | { or: [RuleExpr, RuleExpr] };
export const ruleExprSchema: z.ZodType<RuleExpr> = z.lazy(() => z.union([
  z.object({ c: id }).strict(), z.object({ not: ruleExprSchema }).strict(),
  z.object({ and: z.tuple([ruleExprSchema, ruleExprSchema]) }).strict(), z.object({ or: z.tuple([ruleExprSchema, ruleExprSchema]) }).strict(),
]));
export const ruleSchema = z.object({ if: ruleExprSchema, then: id, else: id }).strict();
export type BuiltRule = z.infer<typeof ruleSchema>;
/** L6 / $9 built chart: a question with a yes and a no branch, down to outcomes. */
export type FlowTree = { o: string } | { q: string; yes: FlowTree; no: FlowTree };
export const flowTreeSchema: z.ZodType<FlowTree> = z.lazy(() => z.union([z.object({ o: id }).strict(), z.object({ q: id, yes: flowTreeSchema, no: flowTreeSchema }).strict()]));
const flowRubric = z.union([
  z.object({ paths: z.record(id, ids(2, 12)) }).strict(),
  z.object({ cases: z.array(z.object({ answers: z.record(id, z.boolean()), outcome: id }).strict()).min(5).max(10) }).strict(),
]);
export const V2_FAMILY_RUBRICS = {
  'logic.rule-checker.v2': z.object({ must_flip_ids: ids(1, 5), roles: z.record(id, z.enum(RULE_CARD_ROLES)).optional() }).strict(),
  'logic.euler.v2': z.object({
    regions: z.record(id, z.enum(EULER_REGIONS)),
    relation: z.enum(EULER_RELATIONS).optional(),
    occupied: z.array(z.enum(EULER_REGIONS)).max(4).optional(),
    conclusion: z.enum(EULER_CONCLUSIONS).optional(),
  }).strict(),
  'logic.flowchart.v2': flowRubric,
  'money.spend-decision.v2': flowRubric,
  'logic.sort-by-rule.v2': z.object({ accepted: z.record(id, z.array(z.object({ bin: id, reason: id }).strict()).min(1).max(4)) }).strict(),
  'money.needs-wants.v2': z.object({ accepted: z.record(id, z.array(z.object({ bin: id, reason: id }).strict()).min(1).max(4)) }).strict(),
  'logic.scam-spotter.v2': z.object({ scam_ids: ids(1, 7), cue_ids: z.record(id, ids(0, 6)).optional() }).strict(),
  'money.scam-check.v2': z.object({ scam_ids: ids(1, 7), cue_ids: z.record(id, ids(0, 6)).optional() }).strict(),
  'money.coin-tray.v2': z.object({ target_minor: positive.max(1_000_000), fewest: z.boolean() }).strict(),
  'money.making-change.v2': z.object({ change_minor: positive.max(1_000_000) }).strict(),
  'money.unit-price.v2': z.object({ unit_prices: z.record(id, z.string().regex(/^\d{1,15}(\/[1-9]\d{0,14}|\.\d{1,12})?$/)), better_id: id }).strict(),
  'logic.rule-builder.v2': z.object({ target: ruleSchema, scenarios: z.array(z.record(id, z.boolean())).min(5).max(10) }).strict(),
  'story.branch.v2': z.object({ acceptable_choice_ids: ids(1, 3) }).strict(),
  'story.dialogue-choice.v2': z.object({ acceptable_choice_ids: ids(1, 3) }).strict(),
  'story.would-you-rather.v2': z.object({ acceptable_choice_ids: ids(1, 2) }).strict(),
} as const;


/**
 * The semantic payload the canonical scorer receives for a family segment:
 * structure only, never labels or copy.
 */
export function v2FamilyScorerPayload(segment: V2FamilySegment): Record<string, unknown> {
  switch (segment.type) {
    case 'logic.rule-checker.v2': return { cardIds: segment.payload.cards.map((card) => card.id) };
    case 'logic.euler.v2': return {
      ...(segment.payload.relation ? { relation: segment.payload.relation } : { chooseRelation: true }),
      itemIds: segment.payload.items.map((item) => item.id),
      ...(segment.payload.mark_occupancy ? { occupancy: true } : {}),
      ...(segment.payload.conclusion ? { conclusion: true } : {}),
    };
    case 'logic.flowchart.v2':
    case 'money.spend-decision.v2': return 'mode' in segment.payload ? {
      mode: 'build', questionIds: segment.payload.questions.map((item) => item.id), outcomeIds: segment.payload.outcomes.map((item) => item.id),
    } : {
      start: segment.payload.start,
      nodes: segment.payload.nodes.map((node) => node.kind === 'question' ? { id: node.id, yes: node.yes, no: node.no } : { id: node.id }),
      scenarioIds: segment.payload.scenarios.map((scenario) => scenario.id),
    };
    case 'logic.sort-by-rule.v2':
    case 'money.needs-wants.v2': return {
      binIds: segment.payload.bins.map((bin) => bin.id), itemIds: segment.payload.items.map((item) => item.id),
      reasonIds: segment.payload.reasons.map((reason) => reason.id),
      ...(segment.payload.switch_after !== undefined && segment.payload.second_bins
        ? { switchAfter: segment.payload.switch_after, secondBinIds: segment.payload.second_bins.map((bin) => bin.id) } : {}),
    };
    case 'logic.scam-spotter.v2':
    case 'money.scam-check.v2': return { messageIds: segment.payload.messages.map((message) => message.id),
      ...(segment.payload.cues ? { cueIds: segment.payload.cues.map((cue) => cue.id) } : {}) };
    case 'money.coin-tray.v2': return { denominations: segment.payload.denominations.map((d) => ({ value: d.value_minor, available: d.available })) };
    case 'money.making-change.v2': return {
      denominations: segment.payload.denominations.map((d) => ({ value: d.value_minor, available: d.available })),
      price: segment.payload.price_minor, paid: segment.payload.paid_minor,
    };
    case 'story.branch.v2': return { choiceIds: segment.payload.options.map((item) => item.id) };
    case 'story.dialogue-choice.v2': return { choiceIds: segment.payload.replies.map((item) => item.id) };
    case 'story.would-you-rather.v2': return { choiceIds: segment.payload.options.map((item) => item.id) };
    case 'money.unit-price.v2': return { scale: segment.payload.currency === 'local' ? 100 : 1,
      offers: segment.payload.offers.map((offer) => ({ id: offer.id, quantity: offer.quantity, price: offer.price_minor })) };
    case 'logic.rule-builder.v2': return { level: segment.payload.level, conditionIds: segment.payload.conditions.map((item) => item.id),
      actionIds: segment.payload.actions.map((item) => item.id) };
    case 'voice.mentor-turn.v2':
    case 'voice.mentor-episode.v2': return {};
  }
}

/** A well-formed sample response the contract validator scores against each rubric (never 'invalid'). */
export function v2FamilySampleResponse(segment: V2FamilySegment): unknown {
  switch (segment.type) {
    case 'logic.rule-checker.v2': return { flipped: [segment.payload.cards[0]!.id] };
    case 'logic.euler.v2': return { placements: Object.fromEntries(segment.payload.items.map((item) => [item.id, 'neither'])),
      ...(segment.payload.choose_relation ? { relation: 'overlap' } : {}), ...(segment.payload.mark_occupancy ? { occupied: ['neither'] } : {}),
      ...(segment.payload.conclusion ? { conclusion: 'possibly' } : {}) };
    case 'logic.flowchart.v2':
    case 'money.spend-decision.v2': {
      if ('mode' in segment.payload) return { tree: { q: segment.payload.questions[0]!.id, yes: { o: segment.payload.outcomes[0]!.id }, no: { o: segment.payload.outcomes[1]!.id } } };
      const byId = new Map(segment.payload.nodes.map((node) => [node.id, node]));
      const path = [segment.payload.start];
      let node = byId.get(segment.payload.start);
      while (node && node.kind === 'question') { node = byId.get(node.yes!); if (node) path.push(node.id); }
      return { paths: Object.fromEntries(segment.payload.scenarios.map((scenario) => [scenario.id, path])) };
    }
    case 'logic.sort-by-rule.v2':
    case 'money.needs-wants.v2': return { placements: Object.fromEntries(segment.payload.items.map((item) => [item.id,
      { bin: sortPhaseBins(segment.payload, item.id)[0]!.id, reason: segment.payload.reasons[0]!.id }])) };
    case 'logic.scam-spotter.v2':
    case 'money.scam-check.v2': return { flagged: [], ...(segment.payload.cues ? { cues: {} } : {}) };
    case 'money.coin-tray.v2': return { counts: Object.fromEntries(segment.payload.denominations.map((d) => [String(d.value_minor), 0])) };
    case 'money.making-change.v2': return { counts: Object.fromEntries(segment.payload.denominations.map((d) => [String(d.value_minor), 0])), sequence: [] };
    case 'story.branch.v2': return { choice: segment.payload.options[0]!.id };
    case 'story.dialogue-choice.v2': return { choice: segment.payload.replies[0]!.id };
    case 'story.would-you-rather.v2': return { choice: segment.payload.options[0].id };
    case 'money.unit-price.v2': return { unit_prices: Object.fromEntries(segment.payload.offers.map((offer) => [offer.id, '0'])), choice: segment.payload.offers[0]!.id };
    case 'logic.rule-builder.v2': return { rule: { if: { c: segment.payload.conditions[0]!.id }, then: segment.payload.actions[0]!.id, else: segment.payload.actions[1]!.id } };
    case 'voice.mentor-turn.v2':
    case 'voice.mentor-episode.v2': return null;
  }
}

/* ── M9 long arithmetic (Appendix P Part 1 M9–M10, GAP-FIX-R1) ─────────────── */

/**
 * The optional written algorithm behind a worked example: long division or
 * long multiplication as a step array of {digit, product, remainder}. For
 * division each step brings down a digit: `digit` is the quotient digit,
 * `product` is digit × divisor and `remainder` what is left. For
 * multiplication each step takes one multiplier digit from the right: `digit`
 * is that digit, `product` the shifted partial product and `remainder` the
 * running total. The steps must be exactly the standard algorithm's, so a
 * renderer can never draw arithmetic that does not add up.
 */
export const longArithmeticSchema = z.discriminatedUnion('kind', [
  z.object({ kind: z.literal('long-division'), dividend: positive.max(99_999), divisor: positive.min(2).max(99),
    steps: z.array(z.object({ digit: z.number().int().min(0).max(9), product: z.number().int().nonnegative(), remainder: z.number().int().nonnegative() }).strict()).min(1).max(6) }).strict(),
  z.object({ kind: z.literal('long-multiplication'), multiplicand: positive.max(9_999), multiplier: positive.min(10).max(99),
    steps: z.array(z.object({ digit: z.number().int().min(0).max(9), product: z.number().int().nonnegative(), remainder: z.number().int().nonnegative() }).strict()).min(2).max(2) }).strict(),
]).refine((value) => sameSteps(value.steps, longArithmeticSteps(value)), 'Long arithmetic steps do not follow the algorithm');

export type LongArithmetic = z.infer<typeof longArithmeticSchema>;
type Step = { digit: number; product: number; remainder: number };

/** The standard algorithm's steps for these operands. */
export function longArithmeticSteps(value: { kind: 'long-division'; dividend: number; divisor: number } | { kind: 'long-multiplication'; multiplicand: number; multiplier: number }): Step[] {
  if (value.kind === 'long-division') {
    const digits = String(value.dividend).split('').map(Number);
    const steps: Step[] = [];
    let current = 0;
    let started = false;
    for (const digit of digits) {
      current = current * 10 + digit;
      if (!started && current < value.divisor) continue;
      started = true;
      const q = Math.floor(current / value.divisor);
      steps.push({ digit: q, product: q * value.divisor, remainder: current - q * value.divisor });
      current -= q * value.divisor;
    }
    return steps.length > 0 ? steps : [{ digit: 0, product: 0, remainder: value.dividend }];
  }
  const multiplierDigits = String(value.multiplier).split('').map(Number).reverse();
  let total = 0;
  return multiplierDigits.map((digit, place) => {
    const product = value.multiplicand * digit * 10 ** place;
    total += product;
    return { digit, product, remainder: total };
  });
}

function sameSteps(left: readonly Step[], right: readonly Step[]): boolean {
  return left.length === right.length && left.every((step, index) => step.digit === right[index]!.digit
    && step.product === right[index]!.product && step.remainder === right[index]!.remainder);
}

/**
 * The backward-fade depth for a worked example from the learner's mastery of
 * the topic's primary KC (Appendix P Part 1 M9–M10; B.6's shared posterior).
 * Novices see every step worked; the fade grows with mastery, and at least
 * the first step always stays worked (a worked example, not a test).
 */
export function masteryFadeCount(stepCount: number, pKnown: number | null): number {
  const maximum = Math.max(0, stepCount - 1);
  if (pKnown === null || !Number.isFinite(pKnown)) return 0;
  const depth = pKnown < 0.4 ? 0 : pKnown < 0.6 ? 1 : pKnown < 0.8 ? 2 : 3;
  return Math.min(maximum, depth);
}

/* ── Appendix P age scope and generic parameters (GAP-FIX-R2 learning) ────── */

/**
 * B.7 part 3 / Appendix P Part 1 (age column) and Part 8, OD-16: each
 * first-release representation has an age range and generic parameters, not
 * one pilot fixture. A document may use a kind when its eligibility lies
 * inside the kind's Appendix P range; `adult` opens the kind to the adult
 * chapters of the same course where Appendix P's money use applies to adults
 * (M9/M10 tax and tip, M14 unit price, M15 discount and tax, M19 compound
 * interest, M20 tax brackets, the $5 ledger and the $3 donut split). Core and
 * the browser both call `v2AgeScopeProblem`, so the two contracts can never
 * drift on who may see a kind.
 */
export const V2_AGE_SCOPE: Readonly<Record<string, { ages: readonly [number, number]; adult: boolean }>> = {
  'math.number-line.fraction.v2': { ages: [9, 12], adult: false }, // M3
  'math.place-value.v2': { ages: [6, 9], adult: false }, // M5
  'math.fraction-area.v2': { ages: [7, 10], adult: false }, // M6
  'math.bar-model.structure.v2': { ages: [8, 13], adult: false }, // M7
  'math.bar-model.answer.v2': { ages: [8, 13], adult: false },
  'math.schema-diagram.structure.v2': { ages: [8, 14], adult: false }, // M8
  'math.schema-diagram.slots.v2': { ages: [8, 14], adult: false },
  'math.schema-diagram.answer.v2': { ages: [8, 14], adult: false },
  'math.worked-example.v2': { ages: [9, 17], adult: true }, // M9/M10: price x quantity, bill splits, tax and tip
  'math.function-machine.v2': { ages: [8, 13], adult: false }, // M13
  'math.ratio-table.v2': { ages: [10, 13], adult: true }, // M14
  'money.unit-price.v2': { ages: [10, 14], adult: true }, // $6 (built on M14)
  'visual.percent-grid.v2': { ages: [10, 14], adult: true }, // M15: discount, sales tax, save 10%
  'logic.savings-rule.v2': { ages: [8, 17], adult: false }, // L2
  'logic.rule-builder.v2': { ages: [8, 17], adult: true }, // L2 (adult chapters build the same rules)
  'money.running-ledger.v2': { ages: [9, 17], adult: true }, // $5
  'visual.growth-comparison.v2': { ages: [12, 17], adult: true }, // M19 / $8
  'visual.tax-bracket.v2': { ages: [14, 17], adult: true }, // M20
  'math.cpa-count.v2': { ages: [6, 12], adult: false }, // M1: 6-9, and 10-12 for new topics
  'money.allocation.v2:waffle': { ages: [6, 9], adult: false }, // $3 via M6 at 6-9
  'money.allocation.v2:donut': { ages: [10, 17], adult: true }, // $3 via M14-M15 at 10+
  // GAP-FIX-R4 (Appendix P Parts 1-3 ages column, Part 4.10, OD-16): every other first-release kind.
  // `adult` follows Appendix P's evidence column: the logic tasks and scam spotting were studied with adults.
  'math.number-line.whole.v2': { ages: [6, 9], adult: false }, // M2
  'logic.rule-checker.v2': { ages: [6, 17], adult: true }, // L1: 6-9 permission rules; 13-17 abstract and causal
  'logic.euler.v2': { ages: [6, 17], adult: true }, // L5: 6-9 two circles; 10-12 nesting; 13-17 syllogisms
  'logic.flowchart.v2': { ages: [7, 17], adult: true }, // L6: 7-9 at most 3 decisions; 13-17 build their own
  'money.spend-decision.v2': { ages: [7, 17], adult: true }, // $9 (on L6, L2)
  'logic.sort-by-rule.v2': { ages: [6, 12], adult: false }, // L10: 6-9 single rule; 10-12 rule switch and "it depends"
  'money.needs-wants.v2': { ages: [6, 12], adult: false }, // $10
  'logic.scam-spotter.v2': { ages: [10, 17], adult: true }, // L12
  'money.scam-check.v2': { ages: [10, 17], adult: true }, // $11
  'money.coin-tray.v2': { ages: [6, 9], adult: false }, // $1
  'money.making-change.v2': { ages: [7, 10], adult: false }, // $2
};

const BAND_AGES: Readonly<Record<string, readonly [number, number]>> = { '6-9': [6, 9], '10-12': [10, 12], '13-17': [13, 17], adult: [18, 119] };

/** Why a kind is not open to this document's pathway, or null when it is. */
export function v2AgeScopeProblem(key: string, document: { age_band: string; eligibility: { minimum_age: number; maximum_age: number } }): string | null {
  const scope = V2_AGE_SCOPE[key];
  if (!scope) return null;
  const band = BAND_AGES[document.age_band];
  const { minimum_age: low, maximum_age: high } = document.eligibility;
  if (!band || high < band[0] || low > band[1]) return 'The eligibility does not match the age band';
  if (document.age_band === 'adult') return scope.adult && low >= 18 ? null : 'This kind is not open to the adult pathway';
  return low >= scope.ages[0] && high <= scope.ages[1] ? null : `This kind is open to ages ${scope.ages[0]}-${scope.ages[1]} only`;
}

/**
 * The generic-parameter rules a pathway adds on top of each payload schema:
 * a waffle draws 100 squares, so its total must divide 100 (10 coins = one
 * row each, 20 = five squares each, ...); a donut keeps at most 40 wedges;
 * children count LittleFounders coins, and only the adult pathway may use the
 * local currency of an explicitly real-world lesson (owner glossary).
 */
export function v2PayloadScopeProblem(segment: { type: string; visual: { type: string }; payload: unknown }, ageBand: string): string | null {
  const payload = segment.payload as Record<string, unknown>;
  const total = typeof payload.total === 'number' ? payload.total : 0;
  const step = typeof payload.step === 'number' ? payload.step : 1;
  if (segment.type === 'money.allocation.v2' && segment.visual.type === 'waffle'
    && (total < 10 || total > 100 || 100 % total !== 0 || step !== 1 || payload.currency !== 'coins')) return 'Invalid waffle parameters';
  if (segment.type === 'money.allocation.v2' && segment.visual.type === 'donut' && (total / step > 40 || total > 100_000)) return 'Invalid donut parameters';
  // L2: 8-9 build a single IF, 10-12 add AND/OR, 13-17 and adults nest and negate.
  if (segment.type === 'logic.rule-builder.v2' && ((payload.level !== 'single' && ageBand === '6-9') || (payload.level === 'nested' && ageBand === '10-12'))) {
    return 'This rule level is not open to this age pathway';
  }
  // L6 / $9: learners build their own charts from 13 (Appendix P "13-17 build their own").
  if ((segment.type === 'logic.flowchart.v2' || segment.type === 'money.spend-decision.v2') && payload.mode === 'build' && ageBand !== '13-17' && ageBand !== 'adult') {
    return 'Building a flowchart is open to ages 13 and up';
  }
  // ($1/$2 trays may show the market's real money: Appendix P allows localised currency in recognition tasks.)
  if ((segment.type === 'math.ratio-table.v2' || segment.type === 'money.unit-price.v2') && payload.currency === 'local' && ageBand !== 'adult') {
    return 'Children count LittleFounders coins';
  }
  // GAP-FIX-R4 (Bible 05 §7 Logic row, Appendix P L6): a 6-9 flowchart walk has at most 3 decision points.
  if ((segment.type === 'logic.flowchart.v2' || segment.type === 'money.spend-decision.v2') && Array.isArray(payload.nodes) && ageBand === '6-9'
    && (payload.nodes as Array<{ kind?: unknown }>).filter((node) => node.kind === 'question').length > 3) {
    return 'A flowchart for ages 6-9 has at most 3 decisions';
  }
  // Bible 05 §7 Logic row: at most 2 inputs for ages 10-12 (the L2 rule builder's AND/OR joins two conditions).
  if (segment.type === 'logic.rule-builder.v2' && ageBand === '10-12' && Array.isArray(payload.conditions) && payload.conditions.length > 2) {
    return 'A rule for ages 10-12 has at most 2 inputs';
  }
  // L1: 6-12 check permission rules only; abstract and causal rules open at 13.
  if (segment.type === 'logic.rule-checker.v2' && payload.rule_kind !== undefined && payload.rule_kind !== 'permission' && (ageBand === '6-9' || ageBand === '10-12')) {
    return 'Abstract and causal rules are open to ages 13 and up';
  }
  if (segment.type === 'logic.euler.v2') {
    const young = ageBand === '6-9';
    // L5: 6-9 place items in two circles (overlapping or apart); nesting, choosing the diagram and region flags open at 10.
    if (young && (payload.relation === 'subset' || payload.choose_relation === true || payload.mark_occupancy === true)) return 'Nested circles and choosing the diagram open at 10';
    // L5: syllogisms (the conclusion step) are for 13-17 and adults.
    if (payload.conclusion !== undefined && (young || ageBand === '10-12')) return 'Syllogism conclusions are open to ages 13 and up';
  }
  // M2 (GAP-FIX-R5; Appendix P M2 "bounded: 0-10, 0-100, 0-1000", Part 4.9 "bounded number lines only").
  if (segment.type === 'math.number-line.whole.v2' && (payload.minimum !== 0 || ![10, 100, 1000].includes(payload.maximum as number))) {
    return 'A whole-number line runs 0-10, 0-100 or 0-1000';
  }
  // L10: 6-9 sort by a single rule; the rule switch and the "it depends" bin open at 10.
  if (segment.type === 'logic.sort-by-rule.v2' && ageBand === '6-9' && (payload.switch_after !== undefined || payload.depends_bin_id !== undefined)) {
    return 'Ages 6-9 sort by a single rule';
  }
  return null;
}

/* ── M5 place value: three places, trades and borrows (GAP-FIX-R2) ───────── */

/**
 * Appendix P M5 ("Trade $1 for 10 dimes; $1.00 - $0.37") and Bible 05 §7
 * (hundreds as berry flats). Three payload forms, all answerless:
 * - `{ total }` (10-29): the first-release pilot, loose ones traded for tens;
 * - `compose`: a start state of hundreds, tens and ones (value = total, up to
 *   999) that the learner regroups into written digits ("ten" trades 10 ones
 *   for a ten, "hundred" 10 tens for a hundred);
 * - `subtract`: minuend and subtrahend; the learner borrows ("borrow-ten",
 *   "borrow-hundred") until every column can be taken away, then writes the
 *   difference. The step replay plays the same trade sequence back.
 */
const placeCount = z.number().int().min(0).max(29);
export const placeValuePayload = z.union([
  z.object({ total: positive.min(10).max(29) }).strict(),
  z.object({ mode: z.literal('compose'), total: positive.min(10).max(999),
    start: z.object({ hundreds: z.number().int().min(0).max(9), tens: placeCount, ones: placeCount }).strict() }).strict()
    .refine((v) => v.start.hundreds * 100 + v.start.tens * 10 + v.start.ones === v.total && (v.start.tens >= 10 || v.start.ones >= 10), 'Invalid place-value start'),
  z.object({ mode: z.literal('subtract'), minuend: positive.min(10).max(999), subtrahend: positive.max(998) }).strict()
    .refine((v) => v.subtrahend < v.minuend && placeValueBorrows(v.minuend, v.subtrahend) > 0, 'Invalid place-value subtraction'),
]);
export type PlaceValuePayload = z.infer<typeof placeValuePayload>;

/** The fewest borrows a column subtraction needs (0 when no column is short). */
export function placeValueBorrows(minuend: number, subtrahend: number): number {
  let hundreds = Math.floor(minuend / 100); let tens = Math.floor(minuend / 10) % 10; let ones = minuend % 10;
  const s = { hundreds: Math.floor(subtrahend / 100), tens: Math.floor(subtrahend / 10) % 10, ones: subtrahend % 10 };
  let borrows = 0;
  if (ones < s.ones) {
    if (tens === 0) { hundreds -= 1; tens += 10; borrows += 1; }
    tens -= 1; ones += 10; borrows += 1;
  }
  if (tens < s.tens) { hundreds -= 1; tens += 10; borrows += 1; }
  return hundreds < s.hundreds ? -1 : borrows;
}

/** The scorer's semantic view: the start columns and, for a subtraction, what is taken away. */
export function placeValueScorerPayload(payload: PlaceValuePayload): { mode: 'compose' | 'subtract'; hundreds: number; tens: number; ones: number; subtrahend: number } {
  if (!('mode' in payload)) return { mode: 'compose', hundreds: 0, tens: 0, ones: payload.total, subtrahend: 0 };
  if (payload.mode === 'compose') return { mode: 'compose', ...payload.start, subtrahend: 0 };
  return { mode: 'subtract', hundreds: Math.floor(payload.minuend / 100), tens: Math.floor(payload.minuend / 10) % 10, ones: payload.minuend % 10, subtrahend: payload.subtrahend };
}

/* ── M8 schema diagrams: change, group, compare, ratio (GAP-FIX-R2) ───────── */

/**
 * Appendix P M8: the learner picks a schema (change, group, compare, ratio)
 * and fills its slots from the text; $4 and $8 build on it. The public payload
 * is schema-neutral: the two story quantities and the label of the unknown.
 * Which schema fits and where each quantity goes live in the private rubric,
 * so a document never reveals the structure it grades.
 */
export const SCHEMA_KINDS = ['change', 'group', 'compare', 'ratio'] as const;
export type SchemaKind = (typeof SCHEMA_KINDS)[number];
export const SCHEMA_SLOTS: Readonly<Record<SchemaKind, readonly [string, string, string]>> = {
  change: ['start', 'change', 'result'],
  group: ['part', 'other', 'total'],
  compare: ['larger', 'smaller', 'difference'],
  ratio: ['rate', 'count', 'total'],
};
const quantity = z.object({ id, value: positive.max(100_000), label: label(40) }).strict();
export const schemaDiagramPayload = z.object({
  quantities: z.tuple([quantity, quantity]),
  unknownLabel: label(40),
  spokenText: label(120),
}).strict().refine((value) => value.quantities[0].id !== value.quantities[1].id && value.quantities[0].id !== 'unknown' && value.quantities[1].id !== 'unknown',
  'Invalid schema-diagram quantities');
export type SchemaDiagramPayload = z.infer<typeof schemaDiagramPayload>;
const slotAssignment = z.record(z.string(), z.union([id, z.literal('unknown')]));
export const SCHEMA_DIAGRAM_RUBRICS = {
  'math.schema-diagram.structure.v2': z.object({ schema: z.enum(SCHEMA_KINDS) }).strict(),
  'math.schema-diagram.slots.v2': z.object({ schema: z.enum(SCHEMA_KINDS), slots: slotAssignment }).strict(),
  'math.schema-diagram.answer.v2': z.object({ target: z.number().int().nonnegative().max(10_000_000_000) }).strict(),
} as const;
export function schemaDiagramScorerPayload(payload: SchemaDiagramPayload): { quantityIds: string[]; values: number[] } {
  return { quantityIds: payload.quantities.map((item) => item.id), values: payload.quantities.map((item) => item.value) };
}

/* ── M7 bar models: part-whole and comparison, built by the learner (GAP-FIX-R3) ── */

/**
 * Appendix P M7 (Part 1; Part 4.1 and 4.5; Bible 05 §4 Build and §7): the
 * child builds the bars from the text. The public payload is schema-neutral
 * (like M8): the two or three quantities the text gives and the label of the
 * unknown. The private rubric names the model and the expected structure:
 * which slot of which bar each quantity labels and which slot is the unknown;
 * the relative lengths follow from the quantities and are checked for
 * consistency by the canonical scorer (`solveBarModel`).
 *
 *   part-whole   one bar split into parts: part-a, part-b (part-c added by
 *                the learner) and the whole bracketed over it;
 *   comparison   two bars: the smaller bar, the larger bar (the smaller
 *                length plus a difference segment), and a total bracket
 *                over both the learner may add.
 *
 * In a comparison a bar may carry no number (null): "Ana has 12 more than
 * Leo; together 50" labels the difference and the total, and asks for Leo.
 */
export const BAR_MODELS = ['part-whole', 'comparison'] as const;
export type BarModelKind = (typeof BAR_MODELS)[number];
export const BAR_MODEL_SLOTS: Readonly<Record<BarModelKind, { required: readonly string[]; optional: readonly string[] }>> = {
  'part-whole': { required: ['part-a', 'part-b', 'whole'], optional: ['part-c'] },
  comparison: { required: ['smaller', 'larger', 'difference'], optional: ['total'] },
};
export const barModelPayload = z.object({
  quantities: z.array(quantity).min(2).max(3),
  unknownLabel: label(40),
  spokenText: label(120),
}).strict().refine((value) => new Set(value.quantities.map((item) => item.id)).size === value.quantities.length
  && value.quantities.every((item) => item.id !== 'unknown'), 'Invalid bar-model quantities');
export type BarModelPayload = z.infer<typeof barModelPayload>;
const barSlot = z.union([id, z.literal('unknown'), z.null()]);
export const BAR_MODEL_RUBRICS = {
  'math.bar-model.structure.v2': z.object({ model: z.enum(BAR_MODELS), slots: z.record(z.string(), barSlot) }).strict(),
  'math.bar-model.answer.v2': z.object({ target: z.number().int().positive().max(1_000_000) }).strict(),
} as const;
export function barModelScorerPayload(payload: BarModelPayload): { quantityIds: string[]; values: number[] } {
  return { quantityIds: payload.quantities.map((item) => item.id), values: payload.quantities.map((item) => item.value) };
}

/* ── M1 fading entry stage (GAP-FIX-R2, Appendix P Part 4.4) ──────────────── */

export const CPA_STAGES = ['concrete', 'pictorial', 'abstract'] as const;
export type CpaStage = (typeof CPA_STAGES)[number];

/**
 * "Support is removed as accuracy rises, and a learner who is already fluent
 * is not sent back to concrete (expertise reversal)." The entry stage of an
 * M1 progression from the learner's mastery of the topic's primary KC (B.6's
 * shared posterior) and the stage at which they last first succeeded without
 * help on the same fading group: the later of the two. A novice, or a learner
 * with no evidence, starts at concrete.
 */
export function cpaEntryStage(pKnown: number | null, priorFirstUnaided: CpaStage | null): CpaStage {
  const fromMastery: CpaStage = pKnown === null || !Number.isFinite(pKnown) || pKnown < 0.6 ? 'concrete' : pKnown < 0.85 ? 'pictorial' : 'abstract';
  const rank = (stage: CpaStage) => CPA_STAGES.indexOf(stage);
  return priorFirstUnaided && rank(priorFirstUnaided) > rank(fromMastery) ? priorFirstUnaided : fromMastery;
}

/* ── Mathematical notation (GAP-FIX-R2, Bible 05 §5, Appendix P Parts 5-6) ── */

/**
 * Notation is authored TeX rendered with KaTeX, loaded only by lessons that
 * declare it (capability `visual.math-notation.v1`). The TeX is locale-neutral
 * with '.' decimals; the renderer writes pt-BR's decimal comma as '{,}'. Every
 * expression keeps its author-written spokenText per locale as the accessible
 * name, and its plain `expression` as the fallback. Only a small command set
 * is accepted, never \href, \url, \html* or \text (copy stays copy).
 */
export const NOTATION_CAPABILITY = 'visual.math-notation.v1';
const TEX_COMMANDS = new Set(['frac', 'dfrac', 'times', 'div', 'cdot', 'sqrt', 'left', 'right', '%', 'le', 'ge', 'approx', 'quad', ',', 'pm']);
export function texProblem(tex: string): string | null {
  if (tex.length < 1 || tex.length > 200 || !/^[0-9a-zA-Z\\{}^_+\-=*/()[\].,:%|\s]+$/.test(tex)) return 'Notation uses digits, letters, operators and braces only';
  for (const match of tex.matchAll(/\\([a-zA-Z]+|.)/g)) if (!TEX_COMMANDS.has(match[1]!)) return `\\${match[1]} is not an allowed notation command`;
  let depth = 0;
  for (const char of tex) { if (char === '{') depth += 1; else if (char === '}') { depth -= 1; if (depth < 0) return 'Unbalanced braces'; } }
  return depth === 0 ? null : 'Unbalanced braces';
}
export const mathNotation = z.string().trim().min(1).max(200).refine((value) => texProblem(value) === null, 'Invalid notation');

/* ── B.24 approach choice (GAP-FIX-R5 learning) ───────────────────────────── */

/**
 * Product 10 Block B "Age-band registers" (autonomy: 10-12 "choice of
 * approach/strategy, not just topic order"; 13-17 and adults keep it) and
 * B.24 ("choosing which of two equally-valid strategies to practice next"):
 * a v2 document may declare two or three named alternative segment chains for
 * the same skill. The learner chooses one before practice, Core pins it on the
 * run and grades that chain only; completion needs the chosen chain and every
 * segment outside the chains. The labels are copy; the ids are data.
 */
const approachOption = z.object({
  id,
  label: z.string().trim().min(1).max(40),
  segment_ids: z.array(id).min(1).max(12),
}).strict();
export const v2ApproachesSchema = z.object({ options: z.array(approachOption).min(2).max(3) }).strict();
export type V2Approaches = z.infer<typeof v2ApproachesSchema>;

/**
 * Why a document's approach chains are not a valid choice, or null. `open` is
 * whether the document's age band offers the approach lever (the register
 * policy's `autonomyOfferForBand(band).approach`, computed by the caller). Every
 * chain is complete and gradable: its segments exist, belong to no other chain,
 * sit together (the chains form one block, each chain contiguous inside it),
 * include at least one server-graded step, and teach the same skill as the
 * other chains; no chain holds an M1 fading stage.
 */
export function v2ApproachesProblem(document: {
  knowledge_component_ids: readonly string[];
  segments: ReadonlyArray<{ id: string; grading: string; knowledge_component_id?: string }>;
  representation_progressions?: ReadonlyArray<{ stages: ReadonlyArray<{ segment_id: string }> }>;
  approaches?: V2Approaches;
}, open: boolean): string | null {
  const approaches = document.approaches;
  if (!approaches) return null;
  if (!open) return 'The approach choice opens at age 10 (the register autonomy mechanism)';
  const options = approaches.options;
  if (new Set(options.map((option) => option.id)).size !== options.length) return 'Duplicate approach id';
  if (new Set(options.map((option) => option.label.toLocaleLowerCase('en-US'))).size !== options.length) return 'Duplicate approach label';
  const position = new Map(document.segments.map((segment, index) => [segment.id, index]));
  const claimed = new Set<string>();
  const primary = document.knowledge_component_ids[0];
  const kcs = new Set<string | undefined>();
  const staged = new Set((document.representation_progressions ?? []).flatMap((progression) => progression.stages.map((stage) => stage.segment_id)));
  const spans: Array<[number, number]> = [];
  for (const option of options) {
    const indexes = option.segment_ids.map((segmentId) => position.get(segmentId));
    if (indexes.some((index) => index === undefined)) return 'An approach names a segment the lesson does not have';
    for (const segmentId of option.segment_ids) {
      if (claimed.has(segmentId)) return 'A segment belongs to two approaches';
      claimed.add(segmentId);
      if (staged.has(segmentId)) return 'A fading stage cannot sit inside an approach';
    }
    const sorted = (indexes as number[]).slice().sort((a, b) => a - b);
    if (sorted.some((index, i) => i > 0 && index !== sorted[i - 1]! + 1) || sorted.some((index, i) => index !== (indexes as number[])[i])) {
      return 'An approach must be one run of segments, in order';
    }
    const chain = sorted.map((index) => document.segments[index]!);
    if (!chain.some((segment) => segment.grading === 'server')) return 'Every approach needs a graded step';
    for (const segment of chain) kcs.add(segment.knowledge_component_id ?? primary);
    spans.push([sorted[0]!, sorted.at(-1)!]);
  }
  if (kcs.size !== 1) return 'Every approach must practise the same skill';
  const ordered = spans.slice().sort((a, b) => a[0] - b[0]);
  if (ordered.some((span, i) => i > 0 && span[0] !== ordered[i - 1]![1] + 1)) return 'The approaches must sit together, one after another';
  return null;
}

/** The approach whose chain holds a segment, or null for a segment every learner plays. */
export function v2ApproachOf(approaches: V2Approaches | undefined, segmentId: string): string | null {
  return approaches?.options.find((option) => option.segment_ids.includes(segmentId))?.id ?? null;
}

/** The segments a learner plays under an approach (null: before choosing, or a document without approaches): the rest are skipped. */
export function v2SegmentsForApproach<T extends { id: string }>(segments: readonly T[], approaches: V2Approaches | undefined, approachId: string | null): T[] {
  if (!approaches) return [...segments];
  return segments.filter((segment) => {
    const chain = v2ApproachOf(approaches, segment.id);
    return chain === null || chain === approachId;
  });
}
